// Nesting depth = 3
func arrow(a, b, c bool) {
	if a {
		if b {
			if c {
				return
			}
		}
	}
}


// 4 return values — flag
func parse(s string) (int, int, int, int) {
	return 1, 2, 3, 4
}

// prefer a struct result
type Result struct{ A, B, C, D int }
func parse(s string) Result { return Result{1, 2, 3, 4} }


// naked return in a long function — flag
func process(items []int) (sum, count, max int) {
	// ... 50+ lines ...
	return
}


// Cognitive complexity = 6 (nesting penalised)
func process(items []int) {
	for _, x := range items {
		if x > 0 {
			switch x {
			case 1:
				if x > 1 {
					return
				}
			}
		}
	}
}
